<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, shallowRef, watch } from "vue";
import { onBeforeRouteLeave, useRoute, useRouter } from "vue-router";
import { ApiError } from "../../api/client";
import { noteLibraryApi, type NoteDraftSource, type NoteFilters, type NoteView, type Revision, type RevisionHistory } from "../../api/noteLibrary";
import { useNoteLibrary } from "../../composables/useNoteLibrary";

const route = useRoute(); const router = useRouter(); const library = useNoteLibrary();
const editing = shallowRef(false); const dirty = shallowRef(false); const draftTitle = shallowRef(""); const draftBody = shallowRef(""); const draftSources = shallowRef<NoteDraftSource[]>([]); const draftVersion = shallowRef(1); const baseRevision = shallowRef(0); const saveStatus = shallowRef("已保存"); const historyOpen = shallowRef(false); const history = shallowRef<RevisionHistory | null>(null); const viewedRevision = shallowRef<Revision | null>(null); const metadataOpen = shallowRef(false); const metadataTags = shallowRef(""); const metadataResearch = shallowRef(""); const conflict = shallowRef<string | null>(null); const searchValue = shallowRef("");
let searchTimer: ReturnType<typeof setTimeout> | null = null; let autosaveTimer: ReturnType<typeof setTimeout> | null = null; let commitKey: string | null = null;
const selectedId = computed(() => typeof route.query.note_id === "string" && /^\d+$/.test(route.query.note_id) ? Number(route.query.note_id) : null);
const filters = computed<NoteFilters>(() => ({ view: (typeof route.query.view === "string" && ["all", "recent", "favorite", "unlinked_research", "archived"].includes(route.query.view) ? route.query.view : "all") as NoteView, query: typeof route.query.q === "string" ? route.query.q : "", tags: toStrings(route.query.tag), researchContextIds: toStrings(route.query.research_id).map(Number).filter(Number.isInteger), page: Math.max(1, Number(route.query.page) || 1), pageSize: ([20, 50, 100].includes(Number(route.query.page_size)) ? Number(route.query.page_size) : 20) as 20 | 50 | 100 }));
const views: { value: NoteView; label: string }[] = [{ value: "all", label: "全部笔记" }, { value: "recent", label: "最近编辑" }, { value: "favorite", label: "收藏" }, { value: "unlinked_research", label: "未关联研究" }, { value: "archived", label: "归档" }];
function toStrings(value: unknown): string[] { return (Array.isArray(value) ? value : value ? [value] : []).filter((item): item is string => typeof item === "string"); }
function formatNoteDate(value: string): string { const date = new Date(value); const now = new Date(); const time = date.toLocaleTimeString("zh-CN", { hour: "2-digit", minute: "2-digit", hour12: false }); const sameDay = date.getFullYear() === now.getFullYear() && date.getMonth() === now.getMonth() && date.getDate() === now.getDate(); if (sameDay) return `今天 ${time}`; const yesterday = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1); if (date.getFullYear() === yesterday.getFullYear() && date.getMonth() === yesterday.getMonth() && date.getDate() === yesterday.getDate()) return `昨天 ${time}`; return `${date.getMonth() + 1}月${date.getDate()}日 ${time}`; }
function queryFor(next: Partial<NoteFilters>, noteId = selectedId.value) { const merged = { ...filters.value, ...next }; return { ...(merged.view !== "all" ? { view: merged.view } : {}), ...(merged.query ? { q: merged.query } : {}), ...(merged.tags.length ? { tag: merged.tags } : {}), ...(merged.researchContextIds.length ? { research_id: merged.researchContextIds.map(String) } : {}), ...(merged.page > 1 ? { page: String(merged.page) } : {}), ...(merged.pageSize !== 20 ? { page_size: String(merged.pageSize) } : {}), ...(noteId ? { note_id: String(noteId) } : {}) }; }
function update(next: Partial<NoteFilters>, noteId = selectedId.value) { void router.replace({ query: queryFor({ ...next, page: next.page ?? (Object.keys(next).some((key) => key !== "page") ? 1 : filters.value.page) }, noteId) }); }
function chooseView(view: NoteView) { update({ view }, null); }
function search(value: string) { searchValue.value = value; if (searchTimer) clearTimeout(searchTimer); searchTimer = setTimeout(() => update({ query: value }), 280); }
function select(id: number) { editing.value = false; void router.replace({ query: queryFor({}, id) }); }
function toggleTag(tag: string) { const tags = filters.value.tags.includes(tag) ? filters.value.tags.filter((item) => item !== tag) : [...filters.value.tags, tag]; update({ tags }, null); }
function toggleResearch(id: number) { const researchContextIds = filters.value.researchContextIds.includes(id) ? filters.value.researchContextIds.filter((item) => item !== id) : [...filters.value.researchContextIds, id]; update({ researchContextIds }, null); }
async function newNote() { const note = await noteLibraryApi.create(); draftTitle.value = ""; draftBody.value = ""; draftSources.value = []; draftVersion.value = 1; baseRevision.value = 0; commitKey = null; await router.replace({ query: queryFor({}, note.id) }); editing.value = true; }
async function beginEdit() { if (!selectedId.value) return; const draft = await noteLibraryApi.getDraft(selectedId.value); draftTitle.value = draft.title; draftBody.value = draft.body; draftSources.value = [...draft.sources]; draftVersion.value = draft.draft_version; baseRevision.value = draft.base_revision; commitKey = null; editing.value = true; }
function scheduleAutosave() { if (!selectedId.value || !editing.value) return; dirty.value = true; saveStatus.value = "正在保存"; if (autosaveTimer) clearTimeout(autosaveTimer); autosaveTimer = setTimeout(() => void saveDraft(), 1000); }
async function saveDraft(): Promise<boolean> { if (!selectedId.value) return false; try { const draft = await noteLibraryApi.saveDraft(selectedId.value, { expectedDraftVersion: draftVersion.value, title: draftTitle.value, body: draftBody.value, sources: draftSources.value }); draftVersion.value = draft.draft_version; baseRevision.value = draft.base_revision; dirty.value = false; saveStatus.value = "草稿已保存"; return true; } catch (cause) { saveStatus.value = "保存失败，可重试"; if (cause instanceof ApiError && cause.status === 409) conflict.value = "草稿已在其他位置更新；本地内容已保留。"; return false; } }
async function commit() { if (!selectedId.value || !draftTitle.value.trim() || !draftBody.value.trim()) { saveStatus.value = "标题和正文不能为空"; return; } if (!(await saveDraft())) return; commitKey ??= crypto.randomUUID(); try { await noteLibraryApi.commit(selectedId.value, { expectedBaseRevision: baseRevision.value, expectedDraftVersion: draftVersion.value, idempotencyKey: commitKey }); commitKey = null; editing.value = false; saveStatus.value = "版本已保存"; await library.select(selectedId.value); await library.load(filters.value); } catch (cause) { conflict.value = cause instanceof ApiError && cause.status === 409 ? "正式保存发生冲突；请重新加载服务端版本或复制本地草稿。" : "正式保存失败，请重试。"; } }
async function toggleFavorite() { if (!library.selected.value) return; const note = library.selected.value; await noteLibraryApi.metadata(note.id, note.metadata_version, { is_favorite: !note.is_favorite }); await Promise.all([library.select(note.id), library.load(filters.value)]); }
function openMetadata() { if (!library.selected.value) return; metadataTags.value = library.selected.value.tags.join(", "); metadataResearch.value = library.selected.value.research_context_ids.join(", "); metadataOpen.value = true; }
async function saveMetadata() { if (!library.selected.value) return; const note = library.selected.value; const tags = metadataTags.value.split(",").map((value) => value.trim()).filter(Boolean); const research_context_ids = metadataResearch.value.split(",").map(Number).filter((value) => Number.isInteger(value) && value > 0); try { await noteLibraryApi.metadata(note.id, note.metadata_version, { tags, research_context_ids }); metadataOpen.value = false; await Promise.all([library.select(note.id), library.load(filters.value)]); } catch (cause) { if (cause instanceof ApiError && cause.status === 409) conflict.value = "元数据已变化；未覆盖服务端更新。"; else throw cause; } }
async function archive() { if (!library.selected.value) return; await noteLibraryApi.archive(library.selected.value.id, !library.selected.value.is_archived); update({}, null); }
async function openHistory(page = 1) { if (!library.selected.value) return; historyOpen.value = true; history.value = await noteLibraryApi.history(library.selected.value.id, page); }
async function viewRevision(revisionNo: number) { if (!selectedId.value) return; viewedRevision.value = await noteLibraryApi.revision(selectedId.value, revisionNo); }
async function restore(revisionNo: number) { if (!library.selected.value) return; await noteLibraryApi.restore(library.selected.value.id, revisionNo, library.selected.value.current_revision, crypto.randomUUID()); historyOpen.value = false; await Promise.all([library.select(library.selected.value.id), library.load(filters.value)]); }
async function copyLocalDraft() { await navigator.clipboard?.writeText(`${draftTitle.value}\n\n${draftBody.value}`); }
function beforeUnload(event: BeforeUnloadEvent) { if (!dirty.value) return; event.preventDefault(); event.returnValue = ""; }
function handleKeyboard(event: KeyboardEvent) { const target = event.target; const isTyping = target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement || target instanceof HTMLSelectElement; if (isTyping && event.key !== "Escape") return; if (editing.value || historyOpen.value || conflict.value) { if (event.key === "Escape") { editing.value = false; historyOpen.value = false; conflict.value = null; } return; } const items = library.items.value; const index = items.findIndex((item) => item.id === selectedId.value); if (event.key === "ArrowDown" && items.length) { event.preventDefault(); select(items[Math.min(items.length - 1, index + 1)]!.id); } if (event.key === "ArrowUp" && items.length) { event.preventDefault(); select(items[Math.max(0, index < 0 ? 0 : index - 1)]!.id); } if (event.key === "Enter" && selectedId.value) void beginEdit(); }
watch(() => route.fullPath, async () => { searchValue.value = filters.value.query; await library.load(filters.value); await library.select(selectedId.value); }, { immediate: true });
onBeforeRouteLeave(() => !dirty.value || window.confirm("草稿尚未保存，确定离开吗？"));
onMounted(() => { window.addEventListener("keydown", handleKeyboard); window.addEventListener("beforeunload", beforeUnload); });
onBeforeUnmount(() => { library.cancel(); window.removeEventListener("keydown", handleKeyboard); window.removeEventListener("beforeunload", beforeUnload); if (searchTimer) clearTimeout(searchTimer); if (autosaveTimer) clearTimeout(autosaveTimer); });
</script>

<template>
  <section class="note-library-page">
    <header class="note-header"><div><h1>笔记库</h1><p>沉淀、整理并连接科研过程中的思考与判断</p></div><label class="search"><span aria-hidden="true">⌕</span><input :value="searchValue" aria-label="搜索笔记" placeholder="搜索标题、内容、来源、研究、标签…" @input="search(($event.target as HTMLInputElement).value)" /></label><button class="primary new-note" type="button" @click="newNote">＋ 新建笔记</button><button class="notification" type="button" aria-label="通知"><svg aria-hidden="true" viewBox="0 0 24 24"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4" /></svg></button></header>
    <p v-if="library.error.value" class="error" role="alert">{{ library.error.value }} <button type="button" @click="library.load(filters)">重试</button></p>
    <div class="note-workspace" data-testid="note-workspace">
      <aside class="note-navigation" data-testid="note-navigation"><h2>笔记</h2><button v-for="view in views" :key="view.value" class="view" :class="{ active: filters.view === view.value }" type="button" @click="chooseView(view.value)"><span>{{ view.label }}</span><b>{{ library.facets.value?.quick_counts?.[view.value] ?? 0 }}</b></button><section class="facet"><h3>研究</h3><button v-for="item in library.facets.value?.research_contexts ?? []" :key="item.id" type="button" :class="{ picked: filters.researchContextIds.includes(item.id) }" @click="toggleResearch(item.id)">● {{ item.name }} <b>{{ item.count }}</b></button></section><section class="facet"><h3>标签</h3><button v-for="item in library.facets.value?.tags ?? []" :key="item.id" type="button" :class="{ picked: filters.tags.includes(item.name) }" @click="toggleTag(item.name)">{{ item.name }} <b>{{ item.count }}</b></button></section></aside>
      <section class="note-list" data-testid="note-list"><header><div><h2>{{ views.find((view) => view.value === filters.view)?.label }}</h2><span>筛选结果 {{ library.page.value?.total ?? 0 }} / 全部 {{ library.page.value?.all_total ?? 0 }}</span></div><select aria-label="每页笔记数" :value="filters.pageSize" @change="update({ pageSize: Number(($event.target as HTMLSelectElement).value) as 20 | 50 | 100 })"><option :value="20">20 / 页</option><option :value="50">50 / 页</option><option :value="100">100 / 页</option></select></header><p v-if="library.loading.value" class="loading" role="status">正在加载笔记…</p><p v-else-if="!library.items.value.length" class="empty">{{ filters.query || filters.tags.length || filters.researchContextIds.length ? "没有匹配的笔记" : "还没有笔记，创建第一条研究记录吧。" }}</p><button v-for="item in library.items.value" :key="item.id" class="note-row" :class="{ selected: selectedId === item.id }" type="button" @click="select(item.id)"><span class="star" :class="{ favorite: item.is_favorite }">{{ item.is_favorite ? "★" : "☆" }}</span><div><h3>{{ item.title || "未命名笔记" }}</h3><p>{{ item.excerpt }}</p><small>来自 {{ item.source_summaries.map((source) => source.title).join("、") || "未附来源" }}　·　{{ item.research_context_summaries.map((research) => research.name).join("、") || "未关联研究" }}</small><span class="chips"><i v-for="tag in item.tags" :key="tag">{{ tag }}</i></span></div><time>{{ formatNoteDate(item.content_updated_at) }}</time></button><footer class="pager"><button :disabled="filters.page <= 1" @click="update({ page: filters.page - 1 })">上一页</button><span>第 {{ library.page.value?.page ?? 1 }} 页</span><button :disabled="!library.page.value || filters.page * filters.pageSize >= library.page.value.total" @click="update({ page: filters.page + 1 })">下一页</button></footer></section>
      <aside class="note-preview" data-testid="note-preview"><template v-if="library.selected.value"><button class="mobile-back" type="button" @click="update({}, null)">← 返回笔记列表</button><header><button class="favorite" type="button" :aria-label="library.selected.value.is_favorite ? '取消收藏' : '收藏笔记'" @click="toggleFavorite">{{ library.selected.value.is_favorite ? "★" : "☆" }}</button><h2>{{ library.selected.value.title || "未命名笔记" }}</h2></header><p class="status">{{ formatNoteDate(library.selected.value.content_updated_at) }} · {{ library.selected.value.is_archived ? "已归档" : "已保存" }} · <button type="button" @click="openHistory()">↻ 历史版本</button></p><article>{{ library.selected.value.body }}</article><section><h3>来源</h3><p v-for="source in library.selected.value.sources" :key="`${source.source_type}-${source.source_id}-${source.title}`">{{ source.title }} <small>{{ source.status === "accessible" ? (source.capabilities.includes("view_source_location") ? "可定位" : "不可定位") : "来源已撤销" }}</small></p></section><section><h3>关联研究</h3><p>{{ library.selected.value.research_context_ids.join("、") || "尚未关联" }}</p></section><button class="primary wide" type="button" @click="beginEdit">继续编辑 →</button><div class="secondary-actions"><button type="button" @click="openMetadata">标签与研究</button><button type="button" @click="openHistory()">历史版本</button><button type="button" @click="archive">{{ library.selected.value.is_archived ? "取消归档" : "归档" }}</button></div></template><p v-else class="empty">选择一条笔记以阅读详情</p></aside>
    </div>
    <div v-if="editing" class="dialog" role="dialog" aria-modal="true" aria-label="编辑笔记"><div><header><h2>编辑笔记</h2><button type="button" aria-label="关闭编辑" @click="editing = false">×</button></header><label>标题<input v-model="draftTitle" @input="scheduleAutosave" /></label><label>正文<textarea v-model="draftBody" @input="scheduleAutosave" /></label><p aria-live="polite">{{ saveStatus }}</p><footer><button type="button" @click="saveDraft">保存草稿</button><button class="primary" type="button" @click="commit">正式保存</button></footer></div></div>
    <div v-if="historyOpen" class="dialog" role="dialog" aria-modal="true" aria-label="历史版本"><div><header><h2>历史版本</h2><button type="button" aria-label="关闭历史版本" @click="historyOpen = false; viewedRevision = null">×</button></header><p v-if="!history">正在加载版本…</p><section v-for="revision in history?.items ?? []" :key="revision.revision_no" class="revision"><strong>版本 {{ revision.revision_no }}</strong><span>{{ revision.title || "未命名笔记" }} · {{ new Date(revision.created_at).toLocaleString("zh-CN") }}</span><div><button type="button" @click="viewRevision(revision.revision_no)">查看内容</button><button type="button" @click="restore(revision.revision_no)">恢复此版本</button></div></section><article v-if="viewedRevision" class="revision-preview"><h3>版本 {{ viewedRevision.revision_no }}</h3><p>{{ viewedRevision.body }}</p></article><footer class="pager"><button :disabled="(history?.page ?? 1) <= 1" @click="openHistory((history?.page ?? 1) - 1)">上一页</button><span>第 {{ history?.page ?? 1 }} 页</span><button :disabled="!history || history.page * history.page_size >= history.total" @click="openHistory((history?.page ?? 1) + 1)">下一页</button></footer></div></div>
    <div v-if="metadataOpen" class="dialog" role="dialog" aria-modal="true" aria-label="编辑标签与研究"><div><header><h2>标签与关联研究</h2><button type="button" aria-label="关闭元数据编辑" @click="metadataOpen = false">×</button></header><label>标签（逗号分隔）<input v-model="metadataTags"></label><label>研究 ID（逗号分隔）<input v-model="metadataResearch" inputmode="numeric"></label><footer><button type="button" @click="metadataOpen = false">取消</button><button class="primary" type="button" @click="saveMetadata">保存元数据</button></footer></div></div>
    <div v-if="conflict" class="dialog" role="alertdialog" aria-modal="true" aria-label="保存冲突"><div><h2>保存冲突</h2><p>{{ conflict }}</p><button type="button" @click="beginEdit(); conflict = null">重新加载服务端版本</button><button type="button" @click="copyLocalDraft">复制本地草稿</button><button type="button" @click="conflict = null">保留本地草稿并对比</button></div></div>
  </section>
</template>

<style scoped>
:global(.shell:has(.note-library-page) .topbar){display:none!important}:global(.shell:has(.note-library-page) .content){min-height:100vh}.note-library-page{min-height:100vh;background:#f8fafc;color:#13213b}.note-header{display:flex;align-items:center;gap:18px;height:80px;padding:0 28px;border-bottom:1px solid #e7edf5;background:#fff}.note-header h1{margin:0;font-size:25px}.note-header p{margin:3px 0 0;color:#74829a;font-size:13px}.search{display:flex;align-items:center;gap:8px;min-width:260px;max-width:430px;margin-left:auto;padding:10px 13px;border:1px solid #dce5f1;border-radius:9px;color:#71809a}.search input{width:100%;border:0;outline:0;color:inherit}.primary{border:0;border-radius:8px;background:#1268ea;color:#fff;padding:11px 16px;font-weight:750;cursor:pointer;box-shadow:0 4px 10px rgb(18 104 234 / 18%)}.note-workspace{display:grid;grid-template-columns:250px minmax(480px,1fr) 410px;min-height:calc(100vh - 80px);gap:12px;padding:12px}.note-navigation,.note-list,.note-preview{min-width:0;border:1px solid #e6edf6;border-radius:14px;background:#fff}.note-navigation{padding:16px}.note-navigation h2,.note-list h2,.note-preview h2{margin:0;font-size:17px}.view,.facet button{display:flex;width:100%;justify-content:space-between;border:0;border-radius:8px;background:transparent;padding:11px 9px;color:#34435d;text-align:left;cursor:pointer}.view.active{background:#eaf2ff;color:#1268ea;font-weight:750}.facet{margin-top:20px;padding-top:16px;border-top:1px solid #edf1f7}.facet h3{margin:0 0 6px;color:#6e7d96;font-size:13px}.facet button{font-size:13px}.facet .picked{color:#1268ea;font-weight:700}.note-list{overflow:hidden}.note-list>header{display:flex;justify-content:space-between;align-items:center;padding:20px 24px 12px}.note-list>header span,.status,small{color:#74829a;font-size:12px}.note-list select{border:1px solid #dce5f1;border-radius:7px;padding:7px;background:#fff}.note-row{display:grid;grid-template-columns:26px 1fr auto;gap:8px;width:100%;border:0;border-t